// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 blockTimestamp) public {
        vm.assume(blockTimestamp > 0);
        vm.assume(blockNumber >= 15);
        vm.roll(blockNumber);
        vm.warp(blockTimestamp);
        address sender = makeAddr("sender");
        vm.deal(sender, 10 ether);
        uint256 beforeBalance = address(c).balance;
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        uint256 afterBalance = address(c).balance;
        if (blockNumber % 15 == 0) {
            assertTrue(afterBalance == 0);
        } else {
            assertTrue(afterBalance == beforeBalance + 10 ether);
        }
    }
}
